import { getVersion } from "@tauri-apps/api/app";
import { useEffect, useRef, useState } from "react";
import logo from "../../src-tauri/icons/128x128.png";
// Generated by `npm run licenses`: one entry per distinct license text.
import NOTICES from "../../THIRD_PARTY_LICENSES.json";
import styles from "./AboutDialog.module.css";

export function AboutDialog({ onClose }: { onClose: () => void }) {
  const ref = useRef<HTMLDialogElement>(null);
  const [version, setVersion] = useState("");

  useEffect(() => {
    ref.current?.showModal();
    getVersion().then(setVersion, () => {});
  }, []);
  return (
    <dialog ref={ref} className={styles.about} onClose={onClose} aria-labelledby="about-title">
      <header className={styles.header}>
        <img src={logo} alt="" width={48} height={48} />
        <div>
          <h2 id="about-title">Parquet Viewer</h2>
          <p>A fast, read-only viewer for Parquet files.</p>
        </div>
        {version && <span className={styles.version}>v{version}</span>}
      </header>
      <div className={styles.body}>
        <h3 className="section-label">Open source licenses</h3>
        <div className={styles.notices}>
          {NOTICES.map((n, i) => (
            <details key={i}>
              <summary>
                <span className={styles.names}>{n.packages.map((p) => p.name).join(", ")}</span>
                <span className={styles.license}>{n.id}</span>
              </summary>
              <p className={styles.packages}>{n.packages.map((p) => `${p.name} ${p.version}`).join(", ")}</p>
              <pre>{n.text || "No license text is shipped with this package."}</pre>
            </details>
          ))}
        </div>
      </div>
      <form method="dialog" className={styles.footer}>
        <button type="submit" className="primary large" autoFocus>
          Close
        </button>
      </form>
    </dialog>
  );
}
